<?php
require_once __DIR__.'/../includes/auth.php';
if (is_logged_in()) redirect('app/dashboard.php');
$error='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
  verify_csrf();
  $email=trim($_POST['email']??''); $password=$_POST['password']??'';
  $stmt=db()->prepare('SELECT u.*, b.name AS branch_name FROM users u LEFT JOIN branches b ON b.id=u.branch_id WHERE u.email=? AND u.is_active=1 LIMIT 1'); $stmt->execute([$email]); $u=$stmt->fetch();
  if ($u && password_verify($password,$u['password'])) { login_user($u); redirect('app/dashboard.php'); }
  $error='Invalid email or password.';
}
?>
